x &:= \1_{3\C} - a_{0} \\
y &:=  \tfrac{\rt_1}{2(\al)}\left((1-\al)\sum_{-1}^{2}a_{i} + (\al^2-2)c\right) + \tfrac{\rt_2}{2}(a_0-a_2+a_1-a_{-1}) 
