		A_0(a_0) &= \la \al a_0 - (a_3 + c), \\
		&\phantom{{}={} \la} \quad \tfrac{\al(3\al-2)(7\al-3)}{2\al-1} a_0 - 2(3\al-2)(a_2 +a_{-2}) - 2(5\al-2)z,\\
